'use client'
import { useRef } from 'react'
import { cn, useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { VisuallyHidden } from '../visually-hidden/visually-hidden'
import styles from './terminal.module.css'

export type TerminalLineType = 'command' | 'output' | 'error' | 'comment'

export interface TerminalLine {
  text: string
  prefix?: string
  type?: TerminalLineType
}

export interface TerminalProps {
  lines: TerminalLine[]
  /**
   * Characters typed per animation frame.
   *
   * @defaultValue `3`
   * @see the component manifest
   */
  speed?: number
  /**
   * Restart from the first line after the last one.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  loop?: boolean
  onComplete?: () => void
  labels?: { label?: string }
  className?: string
}

export function Terminal({
  lines,
  speed = 3,
  loop = false,
  onComplete,
  labels,
  className,
}: TerminalProps) {
  useSignals()
  const lineIndex = useSignal(0)
  const charIndex = useSignal(0)
  const onCompleteRef = useRef(onComplete)
  onCompleteRef.current = onComplete

  useSignalEffect(() => {
    if (lines.length === 0) return
    let rafId: number
    function tick() {
      const li = lineIndex.value
      const ci = charIndex.value
      if (li >= lines.length) {
        onCompleteRef.current?.()
        if (loop) {
          lineIndex.value = 0
          charIndex.value = 0
        } else {
          return
        }
      } else {
        const target = lines[li]!.text
        if (ci < target.length) {
          charIndex.value = ci + speed
        } else {
          lineIndex.value = li + 1
          charIndex.value = 0
        }
      }
      rafId = requestAnimationFrame(tick)
    }
    rafId = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafId)
  })

  const renderedLines = lines.slice(0, lineIndex.value + 1).map((line, i) => {
    const isCurrentLine = i === lineIndex.value
    const text = isCurrentLine ? line.text.slice(0, charIndex.value) : line.text
    return (
      <div key={i} className={styles['line']} data-type={line.type ?? 'output'}>
        {line.prefix && <span className={styles['prefix']}>{line.prefix}</span>}
        <span className={styles['text']}>{text}</span>
        {isCurrentLine && lineIndex.value < lines.length && <span className={styles['cursor']} />}
      </div>
    )
  })

  return (
    <div
      role="group"
      aria-label={labels?.label ?? t(builtin.terminal.label)}
      className={cn(styles['root'], className)}
    >
      {/* Screen readers get the whole script once, in order, from the first render. The
          typing animation is visual only: as a live region it fed them fragments. */}
      <VisuallyHidden>
        {lines.map((line, i) => (
          <span key={i}>
            {line.prefix ? `${line.prefix} ` : ''}
            {line.text}
            {'\n'}
          </span>
        ))}
      </VisuallyHidden>
      <div aria-hidden="true">{renderedLines}</div>
    </div>
  )
}

@layer cascivo.component {
  .root {
    padding: var(--cascivo-space-4);
    overflow-x: auto;
    border: 1px solid var(--cascivo-editor-border, var(--cascivo-color-border));
    border-radius: var(--cascivo-radius-surface);
    background-color: var(--cascivo-terminal-bg, var(--cascivo-editor-bg));
    color: var(--cascivo-terminal-fg, var(--cascivo-editor-fg));
    font-family: var(--cascivo-font-mono);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-relaxed);
  }

  .line {
    display: flex;
    gap: var(--cascivo-space-2);
  }

  .prefix {
    color: var(--cascivo-editor-syntax-string);
    user-select: none;
  }

  .text {
    flex: 1;
    white-space: pre-wrap;

    [data-type='command'] > & {
      color: var(--cascivo-editor-syntax-keyword);
    }

    [data-type='error'] > & {
      color: var(--cascivo-color-destructive);
    }

    [data-type='comment'] > & {
      color: var(--cascivo-editor-syntax-comment);
    }
  }

  .cursor {
    display: inline-block;
    inline-size: 0.5rem;
    block-size: 1em;
    background-color: currentColor;
  }

  /* Decorative loop — opt-in, so a user who expresses no preference gets no motion. */
  @media (prefers-reduced-motion: no-preference) {
    .cursor {
      animation: global(cascivo-blink) var(--cascivo-duration-loop-fast) step-end infinite;
    }
  }
}

@media (forced-colors: active) {
  .root {
    border-color: CanvasText;
  }

  .prefix,
  .text {
    color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Terminal',
  description:
    'An animated terminal that types out a script of commands and output — for demos, onboarding and agent transcripts',
  category: 'display',
  // The visible lines are typed by a requestAnimationFrame loop. The full script is in the
  // server HTML for screen readers, but nothing is visible until JS runs.
  clientJs: 'required',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'lines',
      description:
        'The script. Each line has `text`, an optional `prefix` (e.g. `$`) and a `type` (`command | output | error | comment`, default `output`).',
      type: 'TerminalLine[]',
      required: true,
    },
    {
      name: 'speed',
      description: 'Characters typed per animation frame.',
      type: 'number',
      required: false,
      default: '3',
    },
    {
      name: 'loop',
      description: 'Restart from the first line after the last one.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'onComplete',
      description: 'Called each time the last line finishes typing.',
      type: '() => void',
      required: false,
    },
    {
      name: 'labels',
      description:
        'Overrides for the component’s user-visible strings (i18n) — `label` names the terminal for screen readers.',
      type: '{ label?: string }',
      required: false,
    },
  ],
  typeDefs: [
    {
      name: 'TerminalLine',
      description: 'One line of the script.',
      fields: [
        { name: 'text', type: 'string', required: true, description: 'What the line says.' },
        {
          name: 'prefix',
          type: 'string',
          required: false,
          description: 'A prompt marker such as `$`, styled and not selectable.',
        },
        {
          name: 'type',
          type: "'command' | 'output' | 'error' | 'comment'",
          required: false,
          description: 'Colours the line. Defaults to `output`.',
        },
      ],
    },
  ],
  tokens: [
    '--cascivo-terminal-bg',
    '--cascivo-terminal-fg',
    '--cascivo-editor-bg',
    '--cascivo-editor-fg',
    '--cascivo-editor-border',
    '--cascivo-editor-syntax-keyword',
    '--cascivo-editor-syntax-string',
    '--cascivo-editor-syntax-comment',
    '--cascivo-color-destructive',
    '--cascivo-font-mono',
  ],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: [],
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    {
      title: 'Install transcript',
      code: `<Terminal
  lines={[
    { text: 'npx cascivo add button', prefix: '$', type: 'command' },
    { text: 'Added button to src/components.', type: 'output' },
    { text: '# done in 1.2s', type: 'comment' },
  ]}
/>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  registryDependencies: ['visually-hidden'],
  tags: ['ai', 'terminal', 'cli', 'demo', 'typewriter', 'agent', 'transcript'],
  intent: {
    whenToUse: [
      'Demonstrating a CLI or agent run on a marketing or onboarding page',
      'Replaying a short agent transcript as it happened',
    ],
    whenNotToUse: ['Real, long-running logs — use LogViewer', 'Copyable code — use CodeSnippet'],
    antiPatterns: [
      {
        bad: 'Putting aria-live on the typing lines',
        good: 'Keep the animation aria-hidden and the full script as text, as Terminal does',
        why: 'A live region on per-character typing announces fragments on every frame',
      },
    ],
    related: [
      {
        name: 'LogViewer',
        relationship: 'alternative',
        reason: 'LogViewer is for real, streaming logs with search and follow',
      },
      {
        name: 'CodeSnippet',
        relationship: 'alternative',
        reason: 'CodeSnippet is for static, copyable commands',
      },
    ],
    a11yRationale:
      'A named group whose full script is present as visually hidden text from the first render, read once in order; the typing animation is aria-hidden, so a screen reader is never fed per-character fragments. The cursor blinks only under prefers-reduced-motion: no-preference; colours come from the editor tokens and fall back to CanvasText in forced colours',
    flexibility: [
      {
        area: 'colours',
        level: 'flexible',
        note: 'Follows the editor tokens; override --cascivo-terminal-bg / -fg for an always-dark look',
      },
      { area: 'speed and looping', level: 'flexible', note: 'speed, loop, onComplete' },
    ],
  },
}
